// AgentServiceHandler is an implementation of the nagi.v1.AgentService service.
type AgentServiceHandler interface {
	// ---- 容器 ----
	// 更新节点上缓存的容器配置（端口映射、快照间隔等改了立即生效），不部署。容器第一次放到本节点时检查目录。
	PutContainer(context.Context, *connect.Request[v1.PutContainerRequest]) (*connect.Response[v1.PutContainerResponse], error)
	// 部署一个容器：写好容器目录里的文件、执行 compose、观察 10 秒，成功后缓存这份配置。
	DeployContainer(context.Context, *connect.Request[v1.DeployContainerRequest], *connect.ServerStream[v1.DeployEvent]) error
	// 删除容器：停止并删除它的容器，删除缓存；目录默认保留。
	DeleteContainer(context.Context, *connect.Request[v1.DeleteContainerRequest]) (*connect.Response[v1.DeleteContainerResponse], error)
	// 手动启动、停止或重启容器：不改配置，不生成版本。
	ControlContainer(context.Context, *connect.Request[v1.ControlContainerRequest], *connect.ServerStream[v1.DeployEvent]) error
	// 容器的存储：data/、命名 volume，大小和挂载位置。
	ListVolumes(context.Context, *connect.Request[v1.ContainerRef]) (*connect.Response[v1.ListVolumesResponse], error)
	// 卷里的文件管理，都经 os.Root，不跟随符号链接。snapshot_id 不为空时读快照里的。
	ListVolumeFiles(context.Context, *connect.Request[v1.VolumeFileRef]) (*connect.Response[v1.ListVolumeFilesResponse], error)
	// 下载和上传走 MeshService，大文件不占用控制连接。写操作要持有顶替租约（有顶替时）。
	DeleteVolumeFile(context.Context, *connect.Request[v1.VolumeFileRef]) (*connect.Response[v1.VolumeFileOpResponse], error)
	CreateVolumeDir(context.Context, *connect.Request[v1.VolumeFileRef]) (*connect.Response[v1.VolumeFileOpResponse], error)
	// 把快照里的文件或目录恢复到卷里原来的位置，只覆盖快照里有的文件。
	RestoreVolumeFile(context.Context, *connect.Request[v1.VolumeFileRef]) (*connect.Response[v1.VolumeFileOpResponse], error)
	ListSnapshots(context.Context, *connect.Request[v1.ContainerRef]) (*connect.Response[v1.ListSnapshotsResponse], error)
	CreateSnapshot(context.Context, *connect.Request[v1.ContainerRef], *connect.ServerStream[v1.DeployEvent]) error
	// 从定时或手动快照恢复容器的 data/ 和 volumes/：停止、恢复、重新启动。配置不变。
	RestoreSnapshot(context.Context, *connect.Request[v1.RestoreSnapshotRequest], *connect.ServerStream[v1.DeployEvent]) error
	// 删除一份定时、手动或部署前快照。版本文件不能删（回滚要用）。
	DeleteSnapshot(context.Context, *connect.Request[v1.RestoreSnapshotRequest]) (*connect.Response[v1.VolumeFileOpResponse], error)
	StreamLogs(context.Context, *connect.Request[v1.StreamLogsRequest], *connect.ServerStream[v1.LogLine]) error
	// 在服务的容器里打开一个交互式终端。第一条输入必须是 start。
	Exec(context.Context, *connect.BidiStream[v1.ExecInput, v1.ExecOutput]) error
	// ---- 节点访问：节点的终端和文件（见 docs/node-access.md） ----
	NodeShell(context.Context, *connect.BidiStream[v1.NodeShellInput, v1.ExecOutput]) error
	// 在节点上执行一条命令并等它结束（MCP 的 node_exec）：和终端一样的 shell 和环境变量，不分配终端、没有输入。
	NodeExec(context.Context, *connect.Request[v1.NodeExecRequest], *connect.ServerStream[v1.ExecOutput]) error
	ListNodeDir(context.Context, *connect.Request[v1.NodeFileRef]) (*connect.Response[v1.ListNodeDirResponse], error)
	ReadNodeFile(context.Context, *connect.Request[v1.NodeFileRef]) (*connect.Response[v1.ReadNodeFileResponse], error)
	WriteNodeFile(context.Context, *connect.Request[v1.WriteNodeFileRequest]) (*connect.Response[v1.WriteNodeFileResponse], error)
	DeleteNodeFile(context.Context, *connect.Request[v1.DeleteNodeFileRequest]) (*connect.Response[v1.NodeFileOpResponse], error)
	CreateNodeDir(context.Context, *connect.Request[v1.NodeFileRef]) (*connect.Response[v1.NodeFileOpResponse], error)
	ListNodeFileBackups(context.Context, *connect.Request[v1.NodeFileRef]) (*connect.Response[v1.ListNodeFileBackupsResponse], error)
	RestoreNodeFileBackup(context.Context, *connect.Request[v1.RestoreNodeFileBackupRequest]) (*connect.Response[v1.WriteNodeFileResponse], error)
	// 立即检查容器的镜像有没有新版本。
	CheckImages(context.Context, *connect.Request[v1.ContainerRef]) (*connect.Response[v1.CheckImagesResponse], error)
	// 向仓库验证账号，返回登录后的 docker 配置（config.json），由面板保存。
	LoginRegistry(context.Context, *connect.Request[v1.LoginRegistryRequest]) (*connect.Response[v1.LoginRegistryResponse], error)
	// ---- 备份节点、迁移（见 docs/snapshot.md#异地副本、docs/failover.md#手动迁移） ----
	// 源节点：立即同步一次到备份节点（备份节点在 ContainerSpec.backup 里），同步完才返回。
	SyncBackup(context.Context, *connect.Request[v1.ContainerRef]) (*connect.Response[v1.BackupStatus], error)
	// 目标节点：登记接收一个容器的副本，只接受 source_key 的同步。spec 是容器在本节点上恢复时用的配置（目录是本节点上的）。
	AcceptReplica(context.Context, *connect.Request[v1.AcceptReplicaRequest]) (*connect.Response[v1.AcceptReplicaResponse], error)
	ListReplicas(context.Context, *connect.Request[v1.ListReplicasRequest]) (*connect.Response[v1.ListReplicasResponse], error)
	ListReplicaSnapshots(context.Context, *connect.Request[v1.ContainerRef]) (*connect.Response[v1.ListSnapshotsResponse], error)
	// 目标节点：检查容器能不能放到本节点上（目录可用、端口和域名不冲突），不做任何改动。
	CheckContainer(context.Context, *connect.Request[v1.PutContainerRequest]) (*connect.Response[v1.CheckContainerResponse], error)
	// 目标节点：把副本恢复成本节点上的容器并启动（按 spec 里部署过的版本，不生成新版本），成功后删除副本。
	// snapshot_id 为空时用最新的定时或手动快照。
	RestoreReplica(context.Context, *connect.Request[v1.RestoreReplicaRequest], *connect.ServerStream[v1.DeployEvent]) error
	DeleteReplica(context.Context, *connect.Request[v1.ContainerRef]) (*connect.Response[v1.DeleteReplicaResponse], error)
	// 源节点：迁移的前半段。容器运行时先同步一次，然后停止并移除容器、保存最后一次快照、再增量同步一次。
	MigrateOut(context.Context, *connect.Request[v1.MigrateOutRequest], *connect.ServerStream[v1.DeployEvent]) error
	// 源节点：迁移失败时撤销，重新启动容器。
	MigrateResume(context.Context, *connect.Request[v1.ContainerRef], *connect.ServerStream[v1.DeployEvent]) error
	// ---- 顶替（见 docs/failover.md） ----
	// 保存或删除容器的顶替设置（A、B、见证人各一份）。本节点是 A 或 B 时开始续约或热备。
	SetFailover(context.Context, *connect.Request[v1.SetFailoverRequest]) (*connect.Response[v1.FailoverStatus], error)
	// 热备：确认顶替有状态容器（接受丢失最后一次同步之后的数据）。
	ConfirmTakeover(context.Context, *connect.Request[v1.ContainerRef]) (*connect.Response[v1.FailoverStatus], error)
	// 节点上的全部缓存：容器的配置、顶替设置、代理计划。新面板（或换了主密钥的面板）据此把项目拼回来（见 docs/panel.md#项目数据）。
	GetCache(context.Context, *connect.Request[v1.GetCacheRequest]) (*connect.Response[v1.NodeCache], error)
	// 代理计划（整个替换）：本节点放哪些代理、哪些节点可以连进来。节点缓存在本地。
	SetLinks(context.Context, *connect.Request[v1.LinkPlan]) (*connect.Response[v1.SetLinksResponse], error)
	// 入口节点：检查映射要用的端口有没有被节点上的其他程序占用，不做任何改动。
	CheckPorts(context.Context, *connect.Request[v1.CheckPortsRequest]) (*connect.Response[v1.CheckPortsResponse], error)
	// 让 Caddy 立刻重新申请还没拿到的证书，并清掉 domains 的失败记录。
	RetryCerts(context.Context, *connect.Request[v1.RetryCertsRequest]) (*connect.Response[v1.RetryCertsResponse], error)
	// ---- 节点 ----
	// 面板下发告警配置（渠道和规则）。节点保存在本地，面板挂了也能照常告警。
	SetAlertConfig(context.Context, *connect.Request[v1.SetAlertConfigRequest]) (*connect.Response[v1.SetAlertConfigResponse], error)
	// 查询监控数据。24 小时以内是 10 秒精度，更长是 5 分钟精度。
	QueryMetrics(context.Context, *connect.Request[v1.QueryMetricsRequest]) (*connect.Response[v1.QueryMetricsResponse], error)
	// 磁盘占用：Docker 的镜像、容器、数据卷、构建缓存，以及 Nagi 的容器目录和副本。只读，不清理任何东西。
	GetStorage(context.Context, *connect.Request[v1.GetStorageRequest]) (*connect.Response[v1.NodeStorage], error)
	// 修改项目根目录（之后新放到本节点的容器默认用它）。
	SetProjectsRoot(context.Context, *connect.Request[v1.SetProjectsRootRequest]) (*connect.Response[v1.SetProjectsRootResponse], error)
	// 信任的面板列表。
	ListPanels(context.Context, *connect.Request[v1.ListPanelsRequest]) (*connect.Response[v1.ListPanelsResponse], error)
	// 让节点加入另一个面板（用新面板的令牌），加入后节点同时连接它。
	AddPanel(context.Context, *connect.Request[v1.AddPanelRequest]) (*connect.Response[v1.AddPanelResponse], error)
	// 从信任列表移除一个面板（可以是调用者自己）。不能移除最后一个面板。
	RemovePanel(context.Context, *connect.Request[v1.RemovePanelRequest]) (*connect.Response[v1.RemovePanelResponse], error)
	// mesh 状态：到每个成员走哪条路径。
	GetMeshStatus(context.Context, *connect.Request[v1.MeshStatusRequest]) (*connect.Response[v1.MeshStatus], error)
	// 经 mesh 连一下某个成员，测往返时间。
	MeshPing(context.Context, *connect.Request[v1.MeshPingRequest]) (*connect.Response[v1.MeshPingResponse], error)
	// 节点的镜像加速地址（写在 /etc/docker/daemon.json，重启 Docker 后生效）。
	GetMirrors(context.Context, *connect.Request[v1.GetMirrorsRequest]) (*connect.Response[v1.Mirrors], error)
	SetMirrors(context.Context, *connect.Request[v1.Mirrors]) (*connect.Response[v1.Mirrors], error)
	// 面板绑定的域名（只发给面板自带的节点）：节点的 Caddy 把这个域名反代到面板，证书由 Caddy 申请。为空表示取消。
	SetPanelDomain(context.Context, *connect.Request[v1.SetPanelDomainRequest]) (*connect.Response[v1.SetPanelDomainResponse], error)
	// 升级节点：从 GitHub Release（或安装时指定的镜像）下载 UpgradeRequest.version 指定的 nagi，校验后替换自己并原地重启（容器不受影响）。
	Upgrade(context.Context, *connect.Request[v1.UpgradeRequest]) (*connect.Response[v1.UpgradeResponse], error)
}

